const initialMd=`# 让想法，自然成文\n\n一个安静的空间，装下你所有的灵感。\n\n## 从一段文字开始\n\n好的工具应该隐于幕后，让你专注于内容本身。\n在墨页，Markdown 的简洁与所见即所得的直觉相遇，\n写下的每个字，都以它应有的样子呈现。\n\n> 少一点打扰，多一点心流。让写作回归写作。\n\n## 为你的写作，留一点空间\n\n- 自然书写：输入 Markdown，即刻看到排版结果\n- 灵活组织：拖入元素，让复杂内容变得有条理\n- AI 相伴：需要时展开，不需要时安静收起\n\n### 熟悉的语法，更轻松的表达\n\n| 你想做的事 | 轻松实现 |\n| --- | --- |\n| 组织内容 | 标题、列表与任务清单 |\n| 表达逻辑 | 代码、公式与流程图 |\n| 分享成果 | PDF、HTML 与更多格式 |\n\n## 让 AI 成为你的写作搭档\n\n选择你信任的模型，从本地到云端。润色一段文字，\n梳理一页想法，下一句的灵感也许就在这里。\n\n## 保持简单，保持专注\n\n所有文稿都保存在本地。每个想法，都属于你。`;
const files={'让想法，自然成文.md':initialMd,'桌面编辑器需求.md':'# 桌面编辑器需求\n\n以内容为中心，以自然交互降低学习成本。\n\n## 产品定位\n\n免费开源、本地优先的桌面 Markdown 编辑器。\n\n## 核心体验\n\n- 单界面即时渲染\n- 左侧元素与文件切换\n- 右侧目录定位\n- 可收起的 AI 写作助手\n\n## 多模式写作\n\n源码与预览并排，始终保持清晰。','交互设计笔记.md':'# 交互设计笔记\n\n设计不是添加更多，而是让每一步自然发生。\n\n## 渐进显露\n\n让工具在需要时出现。\n\n## 直接操作\n\n- 元素可以拖入正文\n- 目录可以拖动调宽\n- AI 建议由用户确认后应用\n\n## 清晰反馈\n\n用轻量反馈回应每一次操作。','README.md':'# 欢迎使用墨页\n\n打开一个文稿，让想法自然成文。\n\n## 快速开始\n\n- 点击元素插入内容\n- 试试源码与分屏模式\n- 展开 AI 助手体验模拟响应\n\n## 关于原型\n\n这是本地可运行的交互设计原型。'};
const snippets={heading:'\n## 新的章节\n\n从这里开始书写。',paragraph:'\n写下一段新的想法。',quote:'\n> 在这里留下值得记住的一句话。',list:'\n- 第一个想法\n- 第二个想法\n- 第三个想法',tasks:'\n- [ ] 整理思路\n- [ ] 完成初稿\n- [ ] 分享成果',code:'\n```javascript\nconst idea = "让想法自然成文";\nconsole.log(idea);\n```',table:'\n| 项目 | 说明 |\n| --- | --- |\n| 新的想法 | 值得记录 |',image:'\n![图片说明](./assets/image.png)',link:'\n[链接文字](https://example.com)',callout:'\n> 提示：在这里记录重要的信息。',mermaid:'\n```mermaid\ngraph LR\n  灵感 --> 写作 --> 分享\n```',math:'\n$$\nE = mc^2\n$$'};
