function esc(t){return t.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function inline(t){return esc(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<span class="inline-tag">$1</span>')}
function markdown(md){let out='',inList=false,inCode=false,code='',table=[];const closeList=()=>{if(inList){out+='</ul>';inList=false}};const closeTable=()=>{if(!table.length)return;out+='<table><thead><tr>'+table[0].map(x=>'<th>'+inline(x)+'</th>').join('')+'</tr></thead><tbody>'+table.slice(2).map(row=>'<tr>'+row.map(x=>'<td>'+inline(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';table=[]};md.split('\n').forEach(line=>{if(line.startsWith('```')){closeList();closeTable();if(inCode){out+='<pre>'+esc(code)+'</pre>';code=''}inCode=!inCode;return}if(inCode){code+=line+'\n';return}if(line.startsWith('|')){closeList();table.push(line.split('|').slice(1,-1).map(x=>x.trim()));return}closeTable();if(/^[-*] /.test(line)){if(!inList){out+='<ul>';inList=true}out+='<li>'+inline(line.slice(2)).replace('[ ]','☐').replace('[x]','☑')+'</li>';return}closeList();if(!line.trim())return;const h=line.match(/^(#{1,3}) (.*)/);if(h){out+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;return}if(line.startsWith('> ')){out+='<blockquote>'+inline(line.slice(2))+'</blockquote>';return}out+='<p>'+inline(line)+'</p>'});closeList();closeTable();return out}
